compile.workshop:
variables {
    global:
        0: A
}

rule ("r") {
    event {
        Ongoing - Global;
    }
    actions {
        Set Global Variable(A, 0);
        Set Global Variable(A, -2);
        Set Global Variable(A, 3);
        Set Global Variable(A, 0);
        Set Global Variable(A, 1);
    }
}

rule ("t") {
    event {
        Ongoing - Global;
    }
    actions {
        If(Compare(Current Map, ==, Map(Throne of Anubis)));
            Set Global Variable(A, 1);
        End;
        If(Compare(Custom String("{0}", Current Map), ==, Custom String("{0}", Map(Samoa))));
            Set Global Variable(A, 2);
    }
}

